const alerts=$('Fetch Open Alerts').all().map(i=>i.json);
const incidents=$('Fetch Active Incidents').all().map(i=>i.json);
const corr=$('Active Correlations').all().map(i=>i.json);
const shift=new Date().getHours()<12?'Night':'Day';
const nextShift=shift==='Night'?'Day':'Night';
const brief={shift_ending:shift,shift_starting:nextShift,handover_time:new Date().toISOString(),
  pending_triage:alerts.length,open_incidents:incidents.length,active_correlations:corr.length,
  critical_count:incidents.filter(i=>i.severity==='Critical').length,
  top_alerts:alerts.slice(0,5),top_incidents:incidents.slice(0,3),correlations:corr.slice(0,3)};
return[{json:brief}];

